[7724]={"Fiery Menace!",49,45,255,0,51,0,0,nil,nil,nil,nil,nil,nil,nil,{{14627}},{{14627}},{{{5858}}},"Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.",4550,nil,nil,nil,{nil,{{19125,1}},7000}},
[7725]={"Again With the Zapped Giants",55,45,255,0,357,1,0,{7003},nil,nil,nil,nil,nil,nil,{{14637}},{{14637}},{nil,nil,{{18956}}},"Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",550,nil,nil,18904,{nil,nil,2100}},
