[7841]={"Message to the Wildhammer",48,44,178,0,47,0,7842,nil,nil,nil,nil,nil,nil,nil,{{14738}},{{14738}},{{{2692},{2691},{2694},{2693}}},"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.\nYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.",4400,nil,41},
[7842]={"Another Message to the Wildhammer",48,44,178,0,47,0,7843,{7841},nil,nil,nil,nil,nil,nil,{{14738}},{{14738}},{nil,nil,{{4589}}},"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\nGryphons are known to inhabit every region of the Hinterlands.",5450,nil,41},
[7843]={"The Final Message to the Wildhammer",50,44,178,0,47,2,0,{7842},nil,nil,nil,nil,nil,nil,{{14738}},{{14738}},nil,"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.\nBeware of angry Wildhammer dwarves and unruly members of the Alliance.",5900,nil,41,19036,{nil,{{19119,1}},22000}},
[7844]={"Cannibalistic Cousins",48,44,178,0,47,0,0,nil,nil,nil,nil,nil,nil,nil,{{14739}},{{14739}},{{{4466},{4467}}},"Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 15 Vilebranch Scalpers and 10 Vilebranch Soothsayers. Return to her when this task is complete.\nYayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.",4400,nil,nil,nil,{nil,nil,14000}},
